//! Stable generated bytes do not need a fresh filesystem write. This helper
//! does not replace Cargo's input discovery or absence authentication.
use std::{fs, io, path::Path};

pub(crate) fn write_if_changed(path: impl AsRef<Path>, contents: impl AsRef<[u8]>) -> io::Result<bool> {
    let path = path.as_ref();
    let contents = contents.as_ref();
    match fs::read(path) {
        Ok(existing) if existing == contents => return Ok(false),
        Ok(_) => {},
        Err(error) if error.kind() == io::ErrorKind::NotFound => {},
        Err(error) => return Err(error),
    }
    fs::write(path, contents)?;
    Ok(true)
}

#[cfg(test)]
#[path = "../dmb/shared/test_scratch.rs"]
mod test_scratch;

#[cfg(test)]
mod tests {
    use super::*;
    use std::time::{Duration, UNIX_EPOCH};
    struct Scratch(std::path::PathBuf);
    impl Scratch {
        fn new() -> Self {
            Self(super::test_scratch::dir("build-output"))
        }
        fn path(&self) -> std::path::PathBuf { self.0.join("generated.rs") }
    }
    fn mark(path: &Path) -> std::time::SystemTime {
        let mark = UNIX_EPOCH + Duration::from_secs(978_307_200);
        fs::File::options().write(true).open(path).unwrap()
            .set_times(fs::FileTimes::new().set_modified(mark)).unwrap();
        fs::metadata(path).unwrap().modified().unwrap()
    }
    #[test]
    fn missing_output_is_written_with_exact_bytes() {
        let scratch = Scratch::new(); let path = scratch.path();
        let bytes = b"generated\r\nUnicode:\xc3\xa9\n\0";
        assert!(write_if_changed(&path, bytes).unwrap());
        assert_eq!(fs::read(path).unwrap(), bytes);
    }
    #[test]
    fn identical_output_preserves_its_actual_old_mtime() {
        let scratch = Scratch::new(); let path = scratch.path();
        fs::write(&path, b"same\r\nbytes\n").unwrap(); let before = mark(&path);
        assert!(!write_if_changed(&path, b"same\r\nbytes\n").unwrap());
        assert_eq!(fs::metadata(&path).unwrap().modified().unwrap(), before);
        assert_eq!(fs::read(path).unwrap(), b"same\r\nbytes\n");
    }
    #[test]
    fn same_length_changed_content_is_written_and_reports_change() {
        let scratch = Scratch::new(); let path = scratch.path();
        fs::write(&path, b"old").unwrap(); let before = mark(&path);
        assert!(write_if_changed(&path, b"new").unwrap());
        assert_eq!(fs::read(&path).unwrap(), b"new");
        assert_ne!(fs::metadata(path).unwrap().modified().unwrap(), before);
    }
    #[test]
    fn uncertain_read_is_returned_without_replacing_the_output_path() {
        let scratch = Scratch::new(); let path = scratch.path(); fs::create_dir(&path).unwrap();
        let sentinel = path.join("owned-child"); fs::write(&sentinel, b"keep").unwrap();
        assert!(write_if_changed(&path, b"new").is_err());
        assert!(path.is_dir()); assert_eq!(fs::read(sentinel).unwrap(), b"keep");
    }
    #[test]
    fn missing_parent_keeps_the_real_write_error() {
        let scratch = Scratch::new(); let path = scratch.0.join("missing").join("generated.rs");
        assert_eq!(write_if_changed(&path, b"new").unwrap_err().kind(), io::ErrorKind::NotFound);
        assert!(!path.exists());
    }
}
